18	    private Instant current;
19	
20	    public ControllableClock(Instant initial) {
21	        this.current = initial;
22	    }
23	
24	    public void setInstant(Instant instant) {
25	        this.current = instant;
26	    }
27	
28	    public void advanceSeconds(long seconds) {
29	        this.current = current.plusSeconds(seconds);
30	    }
31	
32	    @Override
33	    public ZoneId getZone() {
34	        return ZoneOffset.UTC;
35	    }
36	
37	    @Override
38	    public Clock withZone(ZoneId zone) {
39	        return Clock.fixed(current, zone);
40	    }
41	
42	    @Override
43	    public Instant instant() {
44	        return current;
45	    }
