48	     * 提供可控 Clock Bean 的测试配置。
49	     */
50	    @TestConfiguration
51	    public static class Config {
52	
53	        @Bean
54	        @Primary
55	        public Clock controllableClock() {
56	            return new ControllableClock(Instant.parse("2026-09-22T00:00:00Z"));
57	        }
58	    }
