package com.example.starter.incident;

/**
 * 封存包内记录类型：ACTION 指令（处置记录）、TRANSFER 交接、TASK 任务状态快照。
 */
public enum SealRecordType {
    ACTION,
    TRANSFER,
    TASK
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 日志封存包头实体，对应 incident_log_seals 表。
 * version 为事件内从 1 开始递增的封存包版本；sealUntil 为封存截至 UTC 时刻
 * （左闭右开区间右端，不含该时刻）。封存后整包不可变，只允许追加更正附录。
 * 时间均为 UTC。
 */
public record IncidentLogSeal(
        long id,
        long incidentId,
        int version,
        Instant sealUntil,
        Instant sealedAt,
        String sealedBy,
        int recordCount,
        int edgeCount,
        Instant createdAt) {
}

package com.example.starter.incident;

import java.time.Instant;

/**
 * 封存包记录明细实体，对应 incident_log_seal_records 表。
 * recordKey 为原记录标识（指令 actionKey / 交接单 id / 任务 taskKey）；
 * recordVersion 为固化时该记录的业务版本（一次性记录为 1，交接 ACCEPTED、
 * 任务 DONE/CANCELLED 为 2）；occurredAt 为记录发生 UTC 时刻；
 * seq 为包内按 (occurredAt, recordKey) 升序的序号；payload 为固化快照 JSON，不可变。
 */
public record SealRecord(
        long id,
        long sealId,
        SealRecordType recordType,
        String recordKey,
        int recordVersion,
        Instant occurredAt,
        int seq,
        String payload) {
}

package com.example.starter.incident;

/**
 * 封存包固化任务依赖边实体，对应 incident_log_seal_edges 表。
 * 有向边：本事件任务 taskKey → 阻塞事件 blockerIncidentKey；
 * seq 为包内按 (taskKey, blockerIncidentKey) 升序的序号。内容不可变。
 */
public record SealEdge(
        long id,
        long sealId,
        String taskKey,
        String blockerIncidentKey,
        int seq) {
}

